<?php require_once __DIR__.'/config.php'; require_login(); verify_csrf(); $id=(int)($_POST['id_producto']??0);$tipo=$_POST['tipo']??'';$cantidad=(int)($_POST['cantidad']??0);$obs=trim($_POST['observacion']??'');if(!in_array($tipo,['entrada','salida'],true)||$cantidad<1){flash('danger','El tipo o la cantidad no son válidos.');redirect('movement_form.php?id='.$id);}try{$pdo=db();$pdo->beginTransaction();$s=$pdo->prepare('SELECT stock_actual FROM productos WHERE id_producto=? AND estado=1 FOR UPDATE');$s->execute([$id]);$p=$s->fetch();if(!$p)throw new RuntimeException('Producto no disponible.');$stock=(int)$p['stock_actual'];if($tipo==='salida'&&$cantidad>$stock)throw new RuntimeException('La salida no puede dejar el stock bajo cero.');$nuevo=$tipo==='entrada'?$stock+$cantidad:$stock-$cantidad;$s=$pdo->prepare('INSERT INTO movimientos(tipo,cantidad,observacion,id_producto,id_usuario) VALUES(?,?,?,?,?)');$s->execute([$tipo,$cantidad,$obs,$id,$_SESSION['user']['id']]);$s=$pdo->prepare('UPDATE productos SET stock_actual=? WHERE id_producto=?');$s->execute([$nuevo,$id]);$pdo->commit();flash('success','Movimiento registrado. El stock fue actualizado.');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();flash('danger',$e->getMessage());}redirect('index.php');
